/**
 * ═══════════════════════════════════════════════════════════════════════════
 * Ο ΔΙΑΤΗΡΗΤΗΣ — «τι ήξερε ο προηγούμενος δείκτης που δεν το λέει ο τίτλος;»
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * ────────────────────────────────────────────────────────────────────────────
 * 🔴 ΤΟ ΓΕΓΟΝΟΣ, ΜΕΤΡΗΜΕΝΟ (ADR-814)
 * ────────────────────────────────────────────────────────────────────────────
 *
 * Ο `generate-adr-index.cjs` δηλώνει στην κεφαλίδα του παραγόμενου αρχείου
 * *«AUTO-GENERATED FILE - Do not edit manually!»* — και **κάποιος τον επεξεργαζόταν
 * χειροκίνητα επί μήνες**. Αποτέλεσμα: **δύο αυθεντίες που απέκλιναν** (ADR-749).
 *
 * Μετρημένο εκτελώντας τον γεννήτορα σε αντίγραφο και συγκρίνοντας:
 *
 * | | |
 * |---|---|
 * | ADR στον παλιό δείκτη | **659** |
 * | ADR στον νέο | **738** ⇒ ο δείκτης ήταν **μπαγιάτικος κατά 79** |
 * | γραμμές που **εξαφανίζονται** | **0** |
 * | κελιά «Decision» **ταυτόσημα** | **575 / 659 = 87,3 %** |
 * | κελιά **πλουσιότερα** στον παλιό | **83** (73 από αυτά κατά **≥200** χαρακτήρες) |
 * | χαρακτήρες που **καταστρέφονταν** | **169.937** — το ADR-777 πήγαινε 10.340 → 137 |
 * | bytes αρχείου | **569.404 → 297.744 (−47,7 %)** |
 *
 * ⇒ Ο γεννήτορας ήταν **πλήρης στην κάλυψη και καταστροφικός στο περιεχόμενο**.
 * Γι' αυτό «μην τον τρέχεις» ήταν σωστή προφύλαξη — και λάθος **θεραπεία**: άφηνε
 * τον δείκτη να παλιώνει για πάντα.
 *
 * ────────────────────────────────────────────────────────────────────────────
 * 🔑 Η ΑΡΧΗ: ΠΡΟΣΘΕΣΕ ΧΩΡΙΣ ΝΑ ΚΑΤΑΣΤΡΕΨΕΙΣ
 * ────────────────────────────────────────────────────────────────────────────
 *
 * Ο τίτλος του ADR είναι ό,τι **ξέρει μηχανικά** ο γεννήτορας. Το επιμελημένο
 * κελί είναι ό,τι **έμαθε άνθρωπος**. Όταν το δεύτερο είναι πλουσιότερο,
 * **κερδίζει** — και ο γεννήτορας το **αναφέρει**, ώστε η διατήρηση να είναι
 * μετρήσιμη αντί για αόρατη.
 *
 * ⚠️ **ΔΗΛΩΜΕΝΟ ΟΡΙΟ**: αν μετονομαστεί ο τίτλος ενός ADR που έχει επιμελημένο
 * κελί, η μετονομασία **ΔΕΝ διαδίδεται** στον δείκτη. Αφορά **83** γραμμές, και
 * γι' αυτό ακριβώς ο γεννήτορας τυπώνει το πλήθος τους: μια σιωπηλή διατήρηση θα
 * ήταν τρίτη αυθεντία· μια **αναφερόμενη** είναι χρέος με όνομα.
 *
 * ⚠️ **ΜΗΝ** «απλοποιήσεις» τον κανόνα σε «κράτα πάντα το παλιό» — τότε ο δείκτης
 * παύει να μαθαίνει από τα ADR και παγώνει οριστικά.
 * ⚠️ **ΜΗΝ** τον κάνεις «κράτα πάντα το νέο» — αυτό είναι ακριβώς η καταστροφή
 * των 169.937 χαρακτήρων που μόλις αποτράπηκε.
 *
 * @module docs/centralized-systems/reference/scripts/lib/preserve-decisions
 * @see ADR-814
 */

'use strict';

/**
 * Το κελί «Decision» είναι η **δεύτερη** στήλη και **των δύο** πινάκων που
 * παράγονται (ο συγκεντρωτικός με 6 στήλες και οι ανά κατηγορία με 4).
 *
 * ⚠️ Το `[^|]*` είναι σκόπιμο: ένα κελί που περιέχει `|` θα έσπαγε τον πίνακα
 * markdown ούτως ή άλλως, οπότε δεν υπάρχει έγκυρη περίπτωση να το χρειαστούμε.
 */
const ROW = /^\|\s*\*\*(ADR-\d+[A-Za-z]*)\*\*\s*\|([^|]*)\|/;

/**
 * Διάβασε τα επιμελημένα κελιά του υπάρχοντος δείκτη.
 *
 * Κρατά το **πλουσιότερο** κελί ανά ADR: το ίδιο ADR εμφανίζεται σε δύο πίνακες
 * και μόνο ο ένας μπορεί να έχει επιμεληθεί.
 *
 * @param {string} markdown το περιεχόμενο του υπάρχοντος `adr-index.md`
 * @returns {Map<string, string>} id → κελί
 */
function readDecisions(markdown) {
  const out = new Map();
  for (const line of String(markdown).split('\n')) {
    const m = ROW.exec(line);
    if (!m) continue;
    const id = m[1];
    const cell = m[2].trim();
    if (!cell) continue;
    const prev = out.get(id);
    if (prev === undefined || cell.length > prev.length) out.set(id, cell);
  }
  return out;
}

/**
 * Ποιο κείμενο μπαίνει στο κελί: το επιμελημένο ή ο τίτλος;
 *
 * @returns {{ text: string, preserved: boolean }}
 */
function chooseDecision(id, generatedTitle, preservedMap) {
  const title = String(generatedTitle || '').trim();
  const curated = preservedMap ? preservedMap.get(id) : undefined;
  // «Πλουσιότερο» = **αυστηρά** μακρύτερο. Ισοπαλία ⇒ κερδίζει ο τίτλος, ώστε
  // ένα ταυτόσημο κελί να μη μετριέται ως «διατηρημένο» και να φουσκώνει τον
  // αριθμό του χρέους (575 από τα 659 είναι ταυτόσημα).
  if (curated !== undefined && curated.length > title.length) {
    return { text: curated, preserved: true };
  }
  return { text: title, preserved: false };
}

/**
 * Ποια ADR **έχασαν** περιγραφή ανάμεσα σε δύο εκδοχές του δείκτη;
 *
 * ────────────────────────────────────────────────────────────────────────────
 * 🔴 ΓΙΑΤΙ ΤΑΥΤΟΤΗΤΑ ΚΑΙ ΟΧΙ ΜΕΓΕΘΟΣ ΑΡΧΕΙΟΥ
 * ────────────────────────────────────────────────────────────────────────────
 *
 * Η πρώτη γραφή του φρουρού συνέκρινε **μήκος αρχείου**. Δοκιμάστηκε και
 * **πυροδότησε για 2 χαρακτήρες** — ένα κενό στο τέλος ενός κελιού που το
 * `trim()` έκοψε. Ένας φρουρός που κοκκινίζει σε κοσμητική διαφορά μαθαίνει τον
 * επόμενο να γράφει `--allow-shrink` **από συνήθεια**, και τότε παύει να φυλάει
 * οτιδήποτε (το σχήμα «μονίμως κόκκινο ⇒ `SKIP_` ⇒ διακοσμητικό» που το
 * CHECK 3.39 δοκίμασε και απέρριψε γραπτώς).
 *
 * Το μέγεθος αρχείου ήταν **προσέγγιση**· η ερώτηση είναι *«έχασε κάποιο ADR
 * την περιγραφή του;»*. Αυτό μετριέται **ανά ADR**, είναι απρόσβλητο σε αλλαγές
 * μορφοποίησης, και όταν πυροδοτεί δίνει **ΟΝΟΜΑΤΑ** αντί για έναν αριθμό.
 * Ίδια κίνηση με το ratchet κατά ταυτότητα του CHECK 3.60.
 *
 * ⚠️ Το ADR που **εξαφανίζεται** μετριέται κι αυτό ως απώλεια: μια γραμμή που
 * χάνεται είναι η ακραία μορφή του «έχασε την περιγραφή του».
 *
 * @returns {Array<{id: string, before: number, after: number}>} ταξινομημένα κατά απώλεια
 */
function findLostDescriptions(previousMarkdown, nextMarkdown) {
  const before = readDecisions(previousMarkdown);
  const after = readDecisions(nextMarkdown);
  const lost = [];
  for (const [id, cell] of before) {
    const now = after.get(id);
    const afterLen = now === undefined ? 0 : now.length;
    if (afterLen < cell.length) lost.push({ id, before: cell.length, after: afterLen });
  }
  lost.sort((a, b) => (b.before - b.after) - (a.before - a.after));
  return lost;
}

module.exports = { ROW, readDecisions, chooseDecision, findLostDescriptions };
